templates.code:
apiVersion: {grupo}/{versión}
kind: {Kind}
metadata:
  name: {nombre}
  namespace: {namespace}
  labels:
    {clave}: {valor}
spec:
  # el estado deseado: cambia según el kind

spec:
  replicas: {n}
  strategy:
    type: RollingUpdate
    rollingUpdate:
      maxSurge: {extra}
      maxUnavailable: {faltantes}

apiVersion: v1
kind: Service
metadata:
  name: {servicio}
spec:
  selector:
    {clave}: {valor}
  ports:
    - name: {nombre_puerto}
      port: {puerto}
      targetPort: {puerto_pod}

spec:
  ingressClassName: {clase}
  rules:
    - http:
        paths:
          - path: {ruta}
            pathType: {tipo}
            backend:
              service:
                name: {servicio}
                port:
                  name: {nombre_puerto}
